            break;
        case MQTT_PACKET_TYPE_PUBLISH:
            objSz = sizeof(MqttPublish);
            break;
        case MQTT_PACKET_TYPE_PUBLISH_ACK:
        case MQTT_PACKET_TYPE_PUBLISH_REC:
        case MQTT_PACKET_TYPE_PUBLISH_REL:
